style.css:
@-moz-document url-prefix("https://www.roblox.com/home") {
:root {
    --my-pink: #bd8581;
    --my-green: #53634a;
    --my-dark: rgba(32, 19, 20, 0.78);
  }

  html {
    background:
      url("https://tr.rbxcdn.com/180DAY-8b4b2008267a65bbab20dcade0179c14/768/432/Image/Png/noFilter")
      center center / cover fixed no-repeat !important;
  }

  body {
    min-height: 100vh !important;
    background: transparent !important;
  }

  #container-main,
  #HomeContainer,
  .dark-theme {
    background-color: transparent !important;
    background-image: none !important;
  }

  #navigation {
    background: var(--my-dark) !important;
    backdrop-filter: blur(8px) !important;
  }

  a,
  a:visited {
    color: var(--my-pink) !important;
  }

  a:hover {
    color: #e8b6ad !important;
  }
}
